// ===============================================================================
// DAEMIND SRE - FILTRO DE MÍDIA E INTENÇÃO DE COMPROVANTE
// ===============================================================================
const body = $json.body || $json;

// Suporta formato Evolution API e Chatwoot
const data = body.data || body;
const message = data.message || {};
const sender = (data.key?.remoteJid || body.sender || '').toString().replace(/@.*$/, '').replace(/\D/g, '');
const caption = (message.imageMessage?.caption || message.documentMessage?.caption || message.conversation || body.content || '').toLowerCase();
const hasMedia = Boolean(message.imageMessage || message.documentMessage || message.extendedTextMessage?.contextInfo?.quotedMessage?.imageMessage || body.attachments?.length > 0);

const isPixIntent = caption.includes('pix') || caption.includes('comprovante') || caption.includes('paguei') || caption.includes('pago') || caption.includes('transferencia') || caption.includes('segue');

const base64Media = data.message?.base64 || body.base64 || '';
const mediaUrl = data.message?.mediaUrl || body.media_url || '';

return [{
  json: {
    sender_whatsapp: sender,
    caption: caption,
    has_media: hasMedia,
    is_pix_intent: isPixIntent,
    base64_media: base64Media,
    media_url: mediaUrl,
    raw_event_id: data.key?.id || body.id || Date.now().toString()
  }
}];

