// ===============================================================================
// DAEMIND SRE - PARSER DE RESPOSTA ESTRUTURADA DA IA
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};

try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    valor: 0.0,
    autenticacao_bancaria: 'MANUAL_REVIEW',
    valido: false
  };
}

return [{
  json: {
    ...parsed,
    valor_extraido: parseFloat(parsed.valor || 0),
    sender_whatsapp: $('Detectar Mídia e Intenção').item.json.sender_whatsapp
  }
}];

